=====================================set_patt	proc EXPORT	tya	Special case, solid	pattern.	and #$FF00	bne begin800;; --- Special case black and white --------------------------------;	tya	and #$00F0	beq @black	cmp #$00F0	bne begin800;	ldy #clrWhite	bra exit801;@black	ldy #clrBlackexit801	ldx #clrBlack>>16	rts;; --- Fill pattern buffer with pattern color ----------;;  y = color/pattern;begin800	pei <work+2	Save work.	pei <work;	ldx <data+2	lda <data	clc	adc #pattern	bcc store800	inxstore800	sta <work	stx <work+2;;	tya	Get pattern color.	lsr a	lsr a	lsr a	lsr a	jsr getcolor	Smear color into all four nibbles.;	sta [<work]	cpy #$0100	bcs dither800;	ldy #30lop800	sta [<work],y	dey	dey	bne lop800	bra exit800;;; --- Special dither pattern -------------------------------------------;dither800	tya	jsr getcolor	tay	and #$F0F0	pha	lda [<work]	and #$0F0F	ora 1,s	sta 1,s;	tya	and #$0F0F	pha	lda [<work]	and #$F0F0	ora 1,s	sta 1,s;	ldy #GraphicsMode-1	lda [<data],y	tax	Keep mode in X.	bpl mode320	What's the mode, 320 or 640?;*** 8-Dec-91 DAL -- use 32-byte patt in 640 mode if ArcRot bit 15 is set!	pha	_GetArcRot	ldx #0	;anticipate arcrot640, handle like 320	pla	bmi mode320	ldx #$8000	;plain 640 mode*** end 8-Dec-91	ldy #14	640 mode index.	bra lop801;mode320	ldy #30	320 mode index.;lop801	jsr set1	txa	bmi skip800	jsr set1;skip800	jsr set2	bmi done800	txa	bmi lop801	jsr set2	bpl lop801;;done800	pla	pla;;exit800	ldy <work	Return pointer to pattern.	ldx <work+2;	pla	Restore work.	sta <work	pla	sta <work+2		rts;;set1	lda 5,s	bra enter2;;set2	lda 3,senter2	sta [<work],y	dey	dey		rts;====================================================================;;   IN:    a = color in low nibble.;;  OUT:    a = color in all four nibbles.;;====================================================================getcolor	and #$000F	pha	asl a	asl a	asl a	asl a	ora 1,s	sta 1,s	xba	ora 1,s	plx		rts;	ENDP;====================================================================;;        Draw a solid rectangle with border.;;  IN:     <rect = RECT to draw.;          <colorptr = pointer to color	table.;          y = color of fill in bits 4-7.;          a = color of outline in bits	4-7.;;====================================================================drawrect	proc EXPORTfillColor	equ 1frameColor	equ fillColor+2;; --- Use special fill & frame RECT call ---------------------;	pha	Save outline color.	phy	Save fill color.;	jsr pushrect	Pass pointer to RECT to draw.	lda frameColor+4,s	Get color of frame,	jsr pushSmear	smear into 4 nibbles and push.	lda fillColor+6,s	Get fill color,	jsr pushSmear	smear into 4 nibbles and push.	_SpecialRect	bcc exit	No error?;	tsc	Fix stack from SpecialRect call.	clc	adc #8	tcs;;; --- Use slower separate fill & frame calls -----------------;	_PenNormal;	jsr setvertpen	Set line size.;	lda frameColor,s	Set pen color.	beq skip1	Color already set?	jsr pushSmear	_SetSolidPenPat;skip1	jsr pushrect	Pass RECT to fill.	lda fillColor+4,s	tay	jsr set_patt	phx	Push pointer to pattern.	phy	_FillRect;	jsr pushrect	Pass RECT to frame.	_FrameRect;exit	ply	Get rid of fill color.	pla	Get rid of outline color.		rts; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = =;;          Smear color and push.;;   IN:    a = color to smear in bits 4-7.;;  OUT:    Color smeared into all 4 nibbles and left on stack.;;100= = = = = = = =	= = = = = = = = = =	= = = = = = = = =pushSmear	plx	Get return address.;	pha	lsr a	lsr a	lsr a	lsr a	ora 1,s	sta 1,s	xba	ora 1,s	sta 1,s;	phx		rts; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = =;;        Get pointer to next control.;;   IN:  Ctlptr = pointer to a control.;;  OUT:  Equal flag	= FALSE if ok, else	no more controls.;;860= = = = = = = =	= = = = = = = = = =	= = = = = = = = =	EXPORT next_Ctlnext_Ctl		;       ;	lda [<Ctlptr]	tax	ldy #2	lda [<Ctlptr],y	bne store860	txy	beq exit860;store860	sta <Ctlhand+2	stx <Ctlhand	jsr dereference	Ctlptr = (Ctlhand).	lda <ctlptr+1	Set not equal flag.exit860	rts; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = =;;          Get bounds RECT of icon.;;   IN:    x = icon	number.;;  OUT:    rect2+y2	= height of character.;          rect2+x2	= width of character.;;870= = = = = = = =	= = = = = = = = = =	= = = = = = = = =	EXPORT get_csizeget_csize		;       ;	stx <work	Pass character to test.; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = =;;   IN:    work = character to get bounds of.;; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = =	EXPORT get_csize2get_csize2		       	lda #getCharBounds;	                  	Fall through to doIconFunc.;; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = =;;          Perform a task that needs the;          icon font as the current font.;;   IN:    a = address of function to perform.;;880= = = = = = = =	= = = = = = = = = =	= = = = = = = = =	EXPORT doIconFuncdoIconFunc		;       	pha	Save function to call.;;; --- Save state of	grafPort ---------------------------------;	pha	Save original text face.	_GetTextFace;	pha	Save original font flags.	_GetFontFlags;	pha	Save original font ID.	pha	_GetFontID;	pha	Save original font	pha	_GetFont;;; --- Clear text face, switch to icon font and call function ------------------;	pea 0000	_SetTextFace;	jsr pushVctl_font	Swicth to icon font.	_SetFont;	pea 4	Use word of color.	_SetFontFlags	pea returnAddr-1	Put return address on stack.;; The stack at this point is;	DefineStackTheRetAddr	word	; 1OrigFont	long	; 3OrigFontID	long	; 7OrigFontFlags	word	; 11OrigTextFace	word	; 13FuncToCall	word	; 15	lda FuncToCall,s	Put address of function on stack,	dec a	pha		rts	and dispatch to it.returnAddr		; ;; --- Restore state	of grafPort ------------------------------;	_SetFont	Restore original font.	_SetFontID	Restore original font ID.	_SetFontFlags	Restore original font flags.	_SetTextFace	Restore original text face.;	pla	Address of function.		rts;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = =;;          Get size	of character.;;   IN:    work = character to get size	of.;;  OUT:    rect2+y2	= height of character.;          rect2+x2	= width of character.;;890= = = = = = = =	= = = = = = = = = =	= = = = = = = = =getCharBounds		; ;	pei <work	Pass character to get bounds of.	jsr pushrect2	Store the bounds in	'rect2'.	_CharBounds;	ldy #rect2+y2	Compute icon's heigth.	lda [<data],y	sec	ldy #rect2+y1	sbc [<data],y	ldy #rect2+y2	sta [<data],y;	ldy #rect2+x2	Compute icon's width.	lda [<data],y	sec	ldy #rect2+x1	sbc [<data],y	ldy #rect2+x2	sta [<data],y		rts; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = =;;        Move control's CtlRect into 'rect'.;;   IN:  Ctlptr = control pointer.;;  OUT:  rect = CtlRect of part.;;900= = = = = = = =	= = = = = = = = = =	= = = = = = = = =	EXPORT CMsetrectCMsetrect		;       	ldy #CtlRect+x2	Put CtlRect into rect.	EXPORT CMsetrect2CMsetrect2		;       	ldx #x2lop900	lda [<Ctlptr],y	sta <rect,x	dey	dey	dex	dex	bpl lop900		rts;	ENDP;            APPEND	CSTATIC.ASM;;====================================================================;;          Static data area.;;====================================================================staticRAM	PROC;;	EXPORT arrowMaparrowMap	DC.W uArrowH,dArrowH,lArrowH,rArrowH;	EXPORT Dimmeddimmed	DC.B $55,$AA,$55,$AA,$55,$AA,$55,$AA Dithered mask for pen.	EXPORT Nor_Masknor_mask	DC.B $FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF Normal mask for pen.;	EXPORT clrBlackclrBlack	DC.W $0000	Solid black pattern.	DC.W $0000	DC.W $0000	DC.W $0000	DC.W $0000	DC.W $0000	DC.W $0000	DC.W $0000	DC.W $0000	DC.W $0000	DC.W $0000	DC.W $0000	DC.W